import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as s,e as t}from"./app-bc94d2a9.js";const e={},o=t(`<h1 id="事务" tabindex="-1"><a class="header-anchor" href="#事务" aria-hidden="true">#</a> 事务</h1><p>Tortoise ORM 支持数据库事务，允许你在操作数据库时将一组操作作为一个不可分割的单元来执行。如果其中任何一个操作失败，整个事务会回滚，以保证数据的一致性。</p><p>以下是 Tortoise ORM 中一些常用的事务管理方法：</p><table><thead><tr><th>方法名称</th><th>说明</th></tr></thead><tbody><tr><td><code>in_transaction()</code></td><td>启动一个新的数据库事务，使用 <code>async with</code> 语法。</td></tr><tr><td><code>atomic()</code></td><td>自动管理事务的装饰器函数，可用于装饰异步函数。</td></tr></tbody></table><h3 id="使用-in-transaction" tabindex="-1"><a class="header-anchor" href="#使用-in-transaction" aria-hidden="true">#</a> 使用 <code>in_transaction()</code></h3><p>这个方法用于在代码块中启动一个新的事务，确保所有操作要么全部成功，要么全部失败：</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> tortoise<span class="token punctuation">.</span>transactions <span class="token keyword">import</span> in_transaction

<span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
    <span class="token keyword">async</span> <span class="token keyword">with</span> in_transaction<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">as</span> connection<span class="token punctuation">:</span>
        event <span class="token operator">=</span> Event<span class="token punctuation">(</span>name<span class="token operator">=</span><span class="token string">&quot;Test&quot;</span><span class="token punctuation">)</span>
        <span class="token keyword">await</span> event<span class="token punctuation">.</span>save<span class="token punctuation">(</span>using_db<span class="token operator">=</span>connection<span class="token punctuation">)</span>
        <span class="token keyword">await</span> Event<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span><span class="token builtin">id</span><span class="token operator">=</span>event<span class="token punctuation">.</span><span class="token builtin">id</span><span class="token punctuation">)</span><span class="token punctuation">.</span>using_db<span class="token punctuation">(</span>connection<span class="token punctuation">)</span><span class="token punctuation">.</span>update<span class="token punctuation">(</span>name<span class="token operator">=</span><span class="token string">&quot;Updated name&quot;</span><span class="token punctuation">)</span>
        <span class="token comment"># 更多数据库操作...</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="使用-atomic" tabindex="-1"><a class="header-anchor" href="#使用-atomic" aria-hidden="true">#</a> 使用 <code>atomic()</code></h3><p>这个方法是一个装饰器，用于自动管理事务：</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> tortoise<span class="token punctuation">.</span>transactions <span class="token keyword">import</span> atomic

<span class="token decorator annotation punctuation">@atomic</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">run</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
    event <span class="token operator">=</span> Event<span class="token punctuation">(</span>name<span class="token operator">=</span><span class="token string">&quot;Test&quot;</span><span class="token punctuation">)</span>
    <span class="token keyword">await</span> event<span class="token punctuation">.</span>save<span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token keyword">await</span> Event<span class="token punctuation">.</span><span class="token builtin">filter</span><span class="token punctuation">(</span><span class="token builtin">id</span><span class="token operator">=</span>event<span class="token punctuation">.</span><span class="token builtin">id</span><span class="token punctuation">)</span><span class="token punctuation">.</span>update<span class="token punctuation">(</span>name<span class="token operator">=</span><span class="token string">&quot;Updated name&quot;</span><span class="token punctuation">)</span>
    <span class="token comment"># 更多数据库操作...</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在这两种方法中，所有的数据库操作都会在一个事务中执行。如果操作中有任何异常发生，事务会自动回滚，以确保数据的一致性。</p><p>如果你有更多问题或者需要更多示例，随时告诉我！</p>`,12),p=[o];function c(i,l){return a(),s("div",null,p)}const r=n(e,[["render",c],["__file","transition.html.vue"]]);export{r as default};
